typedef float time_value_t;
#define NULL 0
#define assert(x) ((void)0)
class stringx { public: stringx(const char*, int = -1); ~stringx(); };
class po {};
class entity_id { unsigned val; public: static entity_id& make_unique_id(); };
class entity { public: void set_time_limited(bool); void frame_done(); };
template<class T> class my_allocator {};
template<class T, class A = my_allocator<T> > class vector { public: T *start, *finish, *end; void push_back(const T&); };
class entity_maker { public: entity* create_entity_or_subclass(const stringx&, entity_id, const po&, const stringx&, unsigned int, const void* = 0); };
extern entity_maker* g_entity_maker;
enum { ACTIVE_FLAG = 1, NONSTATIC_FLAG = 0x80 };
class world_dynamics_system {
public:
  struct ent_time_limit { entity* ent; time_value_t duration; ent_time_limit() : ent(0) {} ent_time_limit(entity* _ent, time_value_t _duration) : ent(_ent), duration(_duration) {} };
  char released_layout[0xd4];
  vector<ent_time_limit> time_limited_entities;
  entity* add_time_limited_effect(const char*, const po&, time_value_t);
};
entity* world_dynamics_system::add_time_limited_effect( const char* name,
                                                       const po& loc,
                                                       time_value_t duration )
{
  entity* e = g_entity_maker->create_entity_or_subclass( name, entity_id::make_unique_id(), loc, "fx\\", ACTIVE_FLAG|NONSTATIC_FLAG );

  assert(e != NULL);

  time_limited_entities.push_back( ent_time_limit(e,duration) );
  e->set_time_limited(true);

  // this needs to be called to set up last-frame info
  e->frame_done();
  return e;
}
